  const g = createGrid(ITEM_ICON_SIZE, ITEM_ICON_SIZE, 0);
  fillRect(g, 3, 3, 10, 10, rampIndex('brass', 3));
  fillRect(g, 4, 4, 3, 3, rampIndex('brass', 5));
  outlineRect(g, 3, 3, 10, 10, OUTLINE);
  return g;
}

